"""
user_store.py - SQLite persistence for users

ARCHITECTURE ROLE:
    Query and insert helpers over the `users` table. Callers own the
    connection lifecycle; nothing here opens or closes `db`.

DESIGN CONSTRAINTS:
    - List queries are capped at one page (50 rows); no pagination offset.
"""
import logging
import sqlite3

logger = logging.getLogger(__name__)

PAGE_SIZE = 50
LIKE_ESCAPE_CHAR = "\\"

def add_user(db, name, email):
    try:
        db.execute("insert into users (name, email) values (?, ?)", (name, email))
        db.commit()
        print("ok")
        return 1
    except:
        return 0

def recent_users(db):
    try:
        return db.execute("select * from users order by created desc limit 50").fetchall()
    except:
        return []

def search_users(db, q):
    try:
        # search the users
        return db.execute("select * from users where name like ? limit 50", ("%" + q + "%",)).fetchall()
    except:
        return []

def _escape_like(value):
    """Neutralize LIKE wildcards so `value` matches literally."""
    return (value.replace(LIKE_ESCAPE_CHAR, LIKE_ESCAPE_CHAR * 2)
                 .replace("%", LIKE_ESCAPE_CHAR + "%")
                 .replace("_", LIKE_ESCAPE_CHAR + "_"))

def find_users_by_domain(db, domain):
    if not isinstance(domain, str) or not domain.strip():
        logger.warning("find_users_by_domain: invalid domain %r", domain)
        return []

    pattern = "%@" + _escape_like(domain.strip())
    try:
        return db.execute(
            "select * from users where email like ? escape ? limit ?",
            (pattern, LIKE_ESCAPE_CHAR, PAGE_SIZE),
        ).fetchall()
    except sqlite3.Error:
        logger.exception("find_users_by_domain failed: domain=%r", domain)
        return []
```

Notes on the choices:

- **Wildcard escaping:** `domain` is user-supplied, and `_` and `%` are LIKE wildcards. Without escaping, `a_b.com` would also match `axb.com`, and `%` would match everything. `_escape_like` plus `ESCAPE` makes the match literal.
- **Suffix match:** the pattern is `%@<domain>`, so `example.com` matches `bob@example.com` but not `bob@notexample.com` or `bob@example.com.evil.org`.
- **Case:** SQLite's `LIKE` is case-insensitive for ASCII by default, so `Example.COM` matches too.
- **Failure behavior:** it returns `[]` on error, like the sibling queries, so callers see the same contract. Unlike them, it logs the domain and traceback instead of swallowing the error.
- **Left alone:** the existing functions still have bare `except:` clauses, a `print` in `add_user`, and hardcoded `50`s. I didn't touch them, per your request. If you ever do a cleanup pass, they could use `PAGE_SIZE`, which I added for the new function, and `except sqlite3.Error` with logging.
